def parse(text):
    try:
        return int(text)
    except ValueError:
        return -1
    finally:
        print("parsed", text)

print(parse("7"), parse("x"))

def half(n):
    if n % 2:
        raise ValueError("odd")
    return n // 2

results = []
for n in [4, 7, 10]:
    try:
        results.append(half(n))
    except ValueError:
        results.append(None)
print(results)

