class Animal:
    def sound(self):
        return "..."

    def speak(self):
        return self.sound()

class Dog(Animal):
    def sound(self):
        return "Woof"

print(Animal().speak(), Dog().speak())

from dataclasses import dataclass

@dataclass
class P:
    x: int
    y: int = 0

print(P(1) == P(1, 0), P(2))

class C:
    def __init__(self, n):
        self.n = n

    @property
    def double(self):
        return self.n * 2

print(C(4).double())

def count_up(n):
    for i in range(n):
        yield i

print(sum(count_up(4)))

def shout(func):
    def wrapper(*args):
        return func(*args).upper() + "!"
    return wrapper

@shout
def greet(name):
    return "hi " + name

print(greet("bo"))
